                ['img' => '05-antechamber', 'alt_en' => 'The antechamber of the Ain Dara temple in 2010, with carved basalt orthostats along the walls', 'alt_ku' => 'پێشژووری پەرستگای عەین دارا لە ٢٠١٠، بە ئۆرتۆستاتی بازاڵتی هەڵکەنراو بە درێژایی دیوارەکان', 'alt_ar' => 'الغرفة الأمامية لمعبد عين دارة عام ٢٠١٠، وعلى جدرانها أورثوستات بازلتية منحوتة', 'caption_en' => 'The antechamber in 2010: basalt slabs with lions and guilloche along the foot of the walls.', 'caption_ku' => 'پێشژوورەکە لە ٢٠١٠: تابلۆی بازاڵت بە شێر و هۆنراوە بە درێژایی بنی دیوارەکان.', 'caption_ar' => 'الغرفة الأمامية عام ٢٠١٠: ألواح بازلتية بأسود وجدائل على امتداد أسفل الجدران.'],
